{"code": "from collections import Counter
import requests

word_url = 'https://raw.githubusercontent.com/dwyl/english-words/master/words_alpha.txt'
response = requests.get(word_url)
word_set = set(response.text.splitlines())

remaining = [
    'ceosentmcnnr', 'ptoroeehlgsamt', 'cacriipblatmes',
    'plneoicohpotthe', 'iouinomatccm', 'nomonimcutica'
]

def unscramble(word):
    low_word = word.lower()
    target_counts = Counter(low_word)
    matches = []
    for w in word_set:
        if len(w) == len(low_word) and Counter(w) == target_counts:
            matches.append(w)
    return matches

results = {s: unscramble(s) for s in remaining}
print(results)"}
